use rust_differential_product_core::{schema::{Catalog,Manifest},generic::{Runtime,Mutation,Query}};
use serde_json::{Value,json};use std::io::{self,BufRead,Write};
fn main(){let mut runtime:Option<Runtime>=None;for line in io::stdin().lock().lines(){let value:Value=serde_json::from_str(&line.unwrap()).unwrap();let result:Result<Value,String>=(||{match value["op"].as_str().unwrap(){"init"=>{let catalog=Catalog::new(serde_json::from_value::<Manifest>(value["catalog"].clone()).map_err(|e|e.to_string())?)?;runtime=Some(Runtime::new(catalog,100_000)?);Ok(json!(true))},"apply"=>{let rows:Vec<Mutation>=serde_json::from_value(value["mutations"].clone()).map_err(|e|e.to_string())?;Ok(json!(runtime.as_mut().unwrap().apply_committed(value["topic"].as_str().unwrap(),value["schema"].as_str().unwrap(),&rows)?))},"open"=>{let query:Query=serde_json::from_value(value["query"].clone()).map_err(|e|e.to_string())?;runtime.as_mut().unwrap().open(value["sub"].as_str().unwrap(),value["topic"].as_str().unwrap(),value["schema"].as_str().unwrap(),query)?;Ok(json!(true))},"read"=>Ok(serde_json::to_value(runtime.as_ref().unwrap().read(value["sub"].as_str().unwrap(),value["offset"].as_u64().unwrap_or(0)as usize,value["limit"].as_u64().unwrap_or(1024)as usize,1_048_576)?).unwrap()),"metrics"=>Ok(runtime.as_ref().unwrap().metrics()),"rows"=>Ok(json!(runtime.as_ref().unwrap().rows(value["topic"].as_str().unwrap(),value["schema"].as_str().unwrap())?)),_=>Err("unknown command".into())}})();println!("{}",match result{Ok(v)=>json!({"ok":v}),Err(e)=>json!({"error":e})});io::stdout().flush().unwrap();}}
